def watershed_sizes(heights: list[list[int]]) -> list[tuple[int, int, int]]:
    if not heights:
        return []

    rows = len(heights)
    cols = len(heights[0])
    if cols == 0:
        return []

    def get_target(r: int, c: int):
        """Return the flow target (nr, nc) for cell (r, c), or None if it's a sink."""
        h = heights[r][c]
        lower = []
        # Check neighbours in priority order: north, east, south, west
        if r - 1 >= 0:
            lower.append((0, (r - 1, c), heights[r - 1][c]))
        if c + 1 < cols:
            lower.append((1, (r, c + 1), heights[r][c + 1]))
        if r + 1 < rows:
            lower.append((2, (r + 1, c), heights[r + 1][c]))
        if c - 1 >= 0:
            lower.append((3, (r, c - 1), heights[r][c - 1]))

        # Keep only strictly lower neighbours
        lower = [x for x in lower if x[2] < h]

        if not lower:
            return None  # sink

        min_h = min(x[2] for x in lower)
        # First in priority order (lowest index wins on ties)
        for x in lower:
            if x[2] == min_h:
                return x[1]

    # Memoized sink-finding (iterative to avoid recursion limits)
    memo = {}  # (r, c) -> (sink_r, sink_c)

    def find_sink(r: int, c: int):
        current = (r, c)
        stack = []
        while current not in memo:
            target = get_target(current[0], current[1])
            if target is None:
                # This cell is a sink
                memo[current] = current
                break
            stack.append(current)
            current = target
        sink = memo[current]
        for node in stack:
            memo[node] = sink
        return sink

    # Count cells draining into each sink
    counts: dict[tuple[int, int], int] = {}
    for r in range(rows):
        for c in range(cols):
            sr, sc = find_sink(r, c)
            counts[(sr, sc)] = counts.get((sr, sc), 0) + 1

    # Sort: count descending, then row ascending, then col ascending
    result = sorted(counts.items(), key=lambda x: (-x[1], x[0][0], x[0][1]))
    return [(r, c, count) for (r, c), count in result]
